import{_ as e,o as a,c as i,ag as s}from"./chunks/framework.DNmTgtHf.js";const g=JSON.parse('{"title":"Part 18 — Authentication","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_18_Authentication.md","filePath":"todo/study_plan/parts/Part_18_Authentication.md"}'),d={name:"todo/study_plan/parts/Part_18_Authentication.md"};function r(n,t,o,l,h,c){return a(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="part-18-—-authentication" tabindex="-1">Part 18 — Authentication <a class="header-anchor" href="#part-18-—-authentication" aria-label="Permalink to &quot;Part 18 — Authentication&quot;">​</a></h1><blockquote><p><strong>Sprint allocation:</strong> Week 9 (shared with Parts 19, 20). <strong>Budget: ~3-4 hrs.</strong></p></blockquote><h2 id="_18-authentication-—-topic-inventory" tabindex="-1">18 Authentication — topic inventory <a class="header-anchor" href="#_18-authentication-—-topic-inventory" aria-label="Permalink to &quot;18 Authentication — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>Password storage done right — Argon2id, bcrypt; never plain hash</td><td>🔴 💼 🔐 🎯</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>(Cross-ref Part 15 password hashing)</td></tr><tr><td>2</td><td>Session vs token-based auth — tradeoffs</td><td>🔴 💼 🔐 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>3</td><td>OAuth 2.0 — roles (resource owner, client, AS, RS), all grant types</td><td>🔴 💼 🔐 🎯</td><td>D</td><td>3 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>4</td><td>Authorization Code flow + PKCE (the right default)</td><td>🔴 💼 🔐 🎯</td><td>D</td><td>2 hrs 20 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: walk through the 5 messages of Auth Code + PKCE from memory — <code>/authorize</code> → <code>/token</code> exchange + code_verifier (20 min)</td></tr><tr><td>5</td><td>OIDC layered on top of OAuth2 — ID token vs access token</td><td>🔴 💼 🔐 🎯</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>6</td><td>JWT — structure (header.payload.signature), JWS vs JWE</td><td>🔴 💼 🔐 🎯</td><td>D</td><td>2 hrs 30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: craft an HS256 JWT manually (header + payload base64url + HMAC), verify on jwt.io (30 min)</td></tr><tr><td>7</td><td>JWT signing algorithms — HS256 vs RS256 vs ES256; alg=none vulnerability</td><td>🔴 💼 🔐 🎯</td><td>D</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>8</td><td>JWT pitfalls — algorithm confusion, missing aud / iss / exp validation, key confusion</td><td>🔴 💼 🔐 🎯</td><td>D</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>9</td><td>Refresh token rotation, reuse detection</td><td>🔴 💼 🔐 🎯</td><td>D</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>10</td><td>SAML — assertions, IdP / SP, when SAML vs OIDC</td><td>🟠 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>11</td><td>LDAP, Kerberos basics (enterprise contexts)</td><td>🟠 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>12</td><td>MFA — TOTP (RFC 6238), WebAuthn / FIDO2, push, SMS (and why SMS is weak)</td><td>🟠 💼 🔐</td><td>MP</td><td>2 hrs 20 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: implement TOTP generator (HMAC-SHA1 over time-counter) from RFC 6238 — verify against Google Authenticator (20 min)</td></tr><tr><td>13</td><td>Magic links, passwordless flows</td><td>🟠 💼 🔐</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>14</td><td>SSO patterns</td><td>🟠 💼 🔐</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>15</td><td>API keys — when to use, rotation strategy</td><td>🟠 💼 🔐</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>16</td><td>mTLS as primary auth between services</td><td>🟠 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>(Cross-ref Parts 16, 17)</td></tr><tr><td>17</td><td>HMAC request signing (AWS SigV4 pattern)</td><td>🟡 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~19.33 hrs</td><td>~1.75 wk</td><td></td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~29.16 hrs</td><td>~2.65 wk</td><td></td></tr><tr><td>Full Part (all items including 🟡)</td><td>~30.66 hrs</td><td>~2.8 wk</td><td></td></tr></tbody></table><h2 id="key-diagrams" tabindex="-1">Key diagrams <a class="header-anchor" href="#key-diagrams" aria-label="Permalink to &quot;Key diagrams&quot;">​</a></h2><p><strong>OAuth 2.0 Authorization Code + PKCE flow:</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant U as User</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant C as Client (mobile / SPA)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant AS as Authorization Server</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant RS as Resource Server</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;C: Generate code_verifier (random)&lt;br/&gt;code_challenge = SHA256(code_verifier)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    U-&gt;&gt;C: Click &quot;Login&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;AS: GET /authorize&lt;br/&gt;+ client_id + redirect_uri + code_challenge + state</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AS-&gt;&gt;U: Login page</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    U-&gt;&gt;AS: Credentials</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AS-&gt;&gt;C: Redirect with code + state</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;AS: POST /token&lt;br/&gt;+ code + code_verifier + client_id</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AS-&gt;&gt;AS: Verify SHA256(code_verifier) == code_challenge</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AS-&gt;&gt;C: access_token + refresh_token + id_token (if OIDC)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;RS: GET /api/data&lt;br/&gt;+ Authorization: Bearer access_token</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    RS-&gt;&gt;RS: Validate JWT signature + aud + iss + exp</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    RS-&gt;&gt;C: Protected data</span></span></code></pre></div><blockquote><p>PKCE prevents code-interception attacks. The code_verifier never leaves the client; only its hash is sent in step 1. An attacker who steals the code can&#39;t redeem it without the verifier.</p></blockquote><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> Walk through Authorization Code + PKCE. Why PKCE, when did it become &quot;the right default&quot;? <ul><li><strong>Why asked:</strong> Senior canonical. PKCE: client generates random code_verifier, sends SHA256 hash in /authorize. Token exchange sends raw code_verifier. AS verifies. Prevents code-interception attacks where mobile/SPA&#39;s redirect URI can be hijacked. Originally for public clients (mobile); now recommended for ALL clients (RFC 9700, 2024).</li></ul></li><li><strong>Q:</strong> JWT structure. What can be in each section? What&#39;s a common pitfall? <ul><li><strong>Why asked:</strong> Senior daily. Header: alg, kid, typ. Payload: iss, sub, aud, exp, iat, jti + custom claims. Signature: HMAC or RSA/ECDSA. Pitfalls: (1) accepting <code>alg=none</code>, (2) algorithm confusion (RS256 → HS256 with public key as HMAC secret), (3) not validating aud/iss/exp, (4) storing sensitive data in payload (it&#39;s base64-encoded, not encrypted — use JWE if you need encryption).</li></ul></li><li><strong>Q:</strong> Refresh token rotation — design + reuse detection. <ul><li><strong>Why asked:</strong> Modern best practice. Rotation: each refresh issues a new refresh_token, invalidates the old one. Reuse detection: if the old (used) refresh_token is presented again, ALL tokens for that user are revoked (probable token theft). Tracks refresh_token &quot;family&quot; — entire chain revocable.</li></ul></li><li><strong>Q:</strong> Session vs token auth — when does each fit? <ul><li><strong>Why asked:</strong> Architecture decision. Session: server-side state, fast revocation, requires sticky sessions OR shared session store. Token (JWT): stateless, scales horizontally, but slow to revoke (must wait for exp or use a blocklist). Hybrid common: short-lived JWT + refresh token + server-side refresh-token tracking.</li></ul></li><li><strong>Q:</strong> SAML vs OIDC — when do you encounter SAML in modern systems? <ul><li><strong>Why asked:</strong> Real-world heterogeneity. SAML: XML-based, enterprise-heavy (B2B SSO with corporate IdPs), older, verbose. OIDC: JSON, mobile/SPA friendly, modern. KYC platform integration with banks may need SAML for the bank&#39;s IdP; consumer-facing should use OIDC.</li></ul></li><li><strong>Q:</strong> MFA — why is SMS considered weak now? <ul><li><strong>Why asked:</strong> Modern security. SIM swap attacks: attacker convinces telco to port victim&#39;s number → receives SMS codes → defeats MFA. Push (with phishing-resistant cert pinning) or TOTP (offline) are stronger. WebAuthn / FIDO2 is strongest — phishing-resistant by design.</li></ul></li><li><strong>Q:</strong> API key — when to use, and how to rotate without downtime? <ul><li><strong>Why asked:</strong> Operational depth. API key for: server-to-server, partner integrations, programmatic API access. Rotation: (1) issue new key, (2) accept BOTH old + new for overlap window (24-72h), (3) deprecate old key, (4) revoke. Communicate with partners. Better: use OAuth Client Credentials instead — built-in rotation via short-lived tokens.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> Your JWT validator accepts a token signed with the public key as HMAC secret. Why? <ul><li><strong>Gotcha:</strong> Algorithm confusion attack. Server expects RS256; attacker crafts token with <code>alg=HS256</code> and signs with the <em>public RSA key</em> as the HMAC secret. Naive validators that read <code>alg</code> from the header and use the same key blindly fail. Fix: pin the expected algorithm; never trust the <code>alg</code> header from the token.</li></ul></li><li><strong>Q:</strong> You set JWT <code>exp=24h</code>. User reports being logged out after 1 hour. Why? <ul><li><strong>Gotcha:</strong> Possible: server clock skew (token rejected because <code>iat</code> or <code>nbf</code> is &quot;in the future&quot;). Or: refresh token had shorter TTL than access token. Or: server-side blocklist. Tip: include 1-2 min clock-skew tolerance in <code>exp</code> validation.</li></ul></li><li><strong>Q:</strong> Your refresh token is <code>Bearer xyz</code> in a cookie. Why is HttpOnly + SameSite=Strict not enough? <ul><li><strong>Gotcha:</strong> Without explicit binding to client (PKCE or DPoP for proof-of-possession), if XSS leaks the token, attacker can use it. HttpOnly stops JS reading the cookie, but XSS can still call your authenticated endpoints from the user&#39;s browser. Mitigations: short refresh TTL, refresh token rotation with reuse detection, IP/UA binding (cautiously — breaks legitimate roaming).</li></ul></li><li><strong>Q:</strong> Your JWT validation passes even though the token was issued by a different OIDC provider. Why? <ul><li><strong>Gotcha:</strong> Missing <code>iss</code> validation. Token-validator must check <code>iss</code> matches the expected authority AND <code>aud</code> matches your service. Without these, ANY valid JWT (signed by any key in your trust store / JWK set) is accepted. Critical for OIDC where many tokens float around.</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>OAuth + OIDC + PKCE end-to-end</strong> (~3 hrs rows 3+4+5) — senior canonical. Walk through the full flow with concrete request/response examples. Code a client + AS toy.</li><li><strong>JWT pitfalls + algorithm confusion deep-dive</strong> (~3 hrs rows 6+7+8) — interview gold. The 5 common JWT bugs. How to validate correctly.</li><li><strong>Refresh token rotation + reuse detection</strong> (~2.5 hrs row 9) — modern best practice. Implement a refresh-token &quot;family&quot; tracker. Auto-revoke on detected reuse.</li><li><strong>JWT design for KYC partner SDK</strong> (~2.5 hrs combined) — short-lived access tokens for SDK, refresh tokens with rotation, key rotation strategy, JWK Set endpoint. Maps directly to your platform.</li></ul><h2 id="hands-on-exercises-practice-advanced" tabindex="-1">Hands-on exercises (Practice + Advanced) <a class="header-anchor" href="#hands-on-exercises-practice-advanced" aria-label="Permalink to &quot;Hands-on exercises (Practice + Advanced)&quot;">​</a></h2><p>Warm-up auth exercises are listed inline in the topic-table Resources column (counted in main Time summary). Longer exercises below are tracked separately.</p><h3 id="practice-—-mid-level-30-60-min-each" tabindex="-1">Practice — mid-level (~30-60 min each) <a class="header-anchor" href="#practice-—-mid-level-30-60-min-each" aria-label="Permalink to &quot;Practice — mid-level (~30-60 min each)&quot;">​</a></h3><ol><li><strong>Craft + validate JWTs in three algorithms</strong> (~45 min) — HS256, RS256, ES256. For each: header, payload, signature. Use Java + Nimbus library. Verify against jwt.io. Then deliberately break each (wrong signature, expired exp, missing aud) and confirm rejection.</li><li><strong>Reproduce the algorithm-confusion vulnerability</strong> (~60 min) — vulnerable validator that reads <code>alg</code> from token + verifies with the key in trust store. Send RS256 token with <code>alg=HS256</code> and public key as HMAC secret. Observe acceptance. Then fix by pinning expected algorithm.</li><li><strong>OAuth Authorization Code + PKCE with Keycloak (local)</strong> (~60 min) — run Keycloak via Docker. Register a client. From <code>curl</code> perform <code>/authorize</code> → callback → <code>/token</code> exchange with code_verifier. Receive access_token. Decode + inspect.</li></ol><h3 id="advanced-—-senior-grade-depth-60-min-each" tabindex="-1">Advanced — senior-grade depth (~60+ min each) <a class="header-anchor" href="#advanced-—-senior-grade-depth-60-min-each" aria-label="Permalink to &quot;Advanced — senior-grade depth (~60+ min each)&quot;">​</a></h3><ol start="4"><li><strong>Refresh-token rotation with reuse detection</strong> (~90 min) — design DB schema for refresh-token family (parent_id, used_at, revoked_at). On each refresh: rotate token, mark old as used. On reuse attempt: revoke entire family + alert. Test happy path + theft scenario.</li><li><strong>JWT design for KYC SDK</strong> (~75 min) — short-lived access token (15 min), refresh token (7 days, rotated on each use, reuse-detected). JWK Set endpoint for key rotation. Validate <code>aud</code>, <code>iss</code>, <code>exp</code>, <code>sub</code>. Sign with ES256 (small token, fast verify).</li></ol><h3 id="hands-on-time-summary-practice-advanced-only" tabindex="-1">Hands-on time summary (Practice + Advanced only) <a class="header-anchor" href="#hands-on-time-summary-practice-advanced-only" aria-label="Permalink to &quot;Hands-on time summary (Practice + Advanced only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Total time</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>Practice (mid-level)</td><td>~2.75 hrs</td><td>~0.25 wk</td><td></td></tr><tr><td>Advanced (senior-grade)</td><td>~2.75 hrs</td><td>~0.25 wk</td><td></td></tr><tr><td><strong>Combined hands-on (Practice + Advanced)</strong></td><td><strong>~5.5 hrs</strong></td><td><strong>~0.5 wk</strong></td><td></td></tr></tbody></table><blockquote><p>Warm-up exercises (counted in main Time summary above) total ~70 min for Part 18 across 3 in-table warm-ups.</p></blockquote><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. PKCE — what does it prevent?</strong> A. Code-interception attacks. The client proves it initiated the auth flow by sending the code_verifier at token exchange (server verifies SHA256 matches the code_challenge it received at /authorize).</p><p><strong>Q. JWT alg=none vulnerability?</strong> A. Unsigned tokens. Vulnerable validators accept tokens with <code>alg=none</code> as valid without signature check. Fix: pin expected algorithm server-side; never trust <code>alg</code> header from the token.</p><p><strong>Q. JWT signing — RS256 vs HS256?</strong> A. HS256: HMAC with shared secret (symmetric). Both parties hold the key. RS256: RSA private signs, public verifies (asymmetric). Use HS256 only when issuer == validator. Use RS256 when issuer ≠ validator (most OIDC).</p><p><strong>Q. Refresh token rotation with reuse detection.</strong> A. Each refresh issues new refresh_token, marks old as used. If old (used) token presented again, revoke entire family. Detects + mitigates token theft.</p><p><strong>Q. SMS MFA — why weak?</strong> A. SIM swap attacks. Attacker convinces telco to port victim&#39;s number, intercepts SMS codes. TOTP (offline) or WebAuthn (phishing-resistant) are stronger.</p><p><strong>Q. What&#39;s the difference between OAuth and OIDC?</strong> A. OAuth = authorization (what you can do). OIDC = authentication layered on top (who you are). OIDC adds the ID token (JWT containing user identity claims) and the userinfo endpoint.</p>`,32)])])}const p=e(d,[["render",r]]);export{g as __pageData,p as default};
